import { Icon } from 'antd'
import moment from 'moment-timezone'
import Cookies from 'universal-cookie'
import { FilterDateRange, FilterInput, FilterSelectPartners } from '../../../../components/tables/helperCells'
import { COLORS } from '../../../../constants/colors'

const cookies = new Cookies()

export function NotificationTable ({
  handleDetailPage,
  searchTextQuery,
  handleInputChange,
  handleSearch,
  isFilterVisible,
  setIsFilterVisible,
  recipients,
  notificationStatus,
  isChange,
  onSearchDate
}) {
  return [
    {
      key: 'number',
      title: 'Number',
      dataIndex: 'number',
      align: 'center'
    },
    {
      key: 'title',
      title: 'Title',
      dataIndex: 'title',
      align: 'center',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.title && COLORS.blue
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='title'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.title : ''}
          onInputChange={e => handleInputChange(e, 'title')}
          onSearch={e => handleSearch(e, 'title')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'title',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'title' : searchTextQuery.title)
    },
    {
      key: 'recipients',
      title: 'Recipients',
      dataIndex: 'recipients',
      align: 'center',
      filterDropdown: (
        <FilterSelectPartners
          idIdentifier='recipients'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.recipients : ''}
          onInputChange={e => handleInputChange(e, 'recipients')}
          onSearch={e => handleSearch(e, 'recipients')}
          partners={recipients}
          placeholder='Select Recipients...'
        />
      ),
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.recipients && COLORS.blue
          }}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'recipients',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'recipients' : searchTextQuery.recipients)
    },
    {
      key: 'created_at',
      title: 'Created At',
      dataIndex: 'created_at',
      align: 'center',
      render: (val, record) => {
        const userTimeZone = cookies.get('userProfile').user_timezone
        return moment(val).tz(userTimeZone).format('MMM DD,YYYY hh:mm A')
      },
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.created_at_start && searchTextQuery.created_at_end && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterDateRange
          idIdentifier='created_at'
          onInputChange={e => handleInputChange(e, 'created_at')}
          onSearch={(e) => onSearchDate(e, 'created_at')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'created_at',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'created_at' : searchTextQuery.created_at_start)
    },
    {
      key: 'published_at',
      title: 'Publish At',
      dataIndex: 'published_at',
      align: 'center',
      render: (val, record) => {
        const userTimeZone = cookies.get('userProfile').user_timezone
        return val ? moment(val).tz(userTimeZone).format('MMM DD,YYYY hh:mm A') : ''
      },
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.published_at_start && searchTextQuery.published_at_end && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterDateRange
          idIdentifier='published_at'
          onInputChange={e => handleInputChange(e, 'published_at')}
          onSearch={(e) => onSearchDate(e, 'published_at')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'published_at',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'published_at' : searchTextQuery.published_at_start)
    },
    {
      key: 'notification_status',
      title: 'Broadcast Status',
      dataIndex: 'notification_status',
      align: 'center',
      filterDropdown: (
        <FilterSelectPartners
          idIdentifier='notification_status'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.notification_status : ''}
          onInputChange={e => handleInputChange(e, 'notification_status')}
          onSearch={e => handleSearch(e, 'notification_status')}
          partners={notificationStatus}
          placeholder='Select Broadcast Status...'
        />
      ),
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.notification_status && COLORS.blue
          }}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'notification_status',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'notification_status' : searchTextQuery.notification_status)
    },
    {
      key: 'creator',
      title: 'Creator',
      dataIndex: 'creator',
      align: 'center',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.creator && COLORS.blue
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='creator'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.creator : ''}
          onInputChange={e => handleInputChange(e, 'creator')}
          onSearch={e => handleSearch(e, 'creator')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'creator',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'creator' : searchTextQuery.creator)
    },
    {
      key: 'action',
      title: 'Action',
      dataIndex: 'action',
      align: 'center',
      render: (val, record) => (
        <Icon
          type={record.notification_status === 'Published' ? 'info-circle' : 'edit'}
          className='isoEditIcon'
          onClick={() => handleDetailPage(record)}
        />
      )
    }
  ]
}

