export const renderBroadCastStatus = (type) => {
  switch (type) {
    case 'PUSH-NOTIF-DRAFT': return 'Draft'
    case 'PUSH-NOTIF-SCHEDULED': return 'Scheduled'
    case 'PUSH-NOTIF-PUBLISHED': return 'Published'
    default: return ''
  }
}

