import { resetError, useErrorContextValue, useLoaderContextValue, useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useRef } from 'react'
import { showNotification } from '../../../../../components/ShowNotification'
import { useNotificationCenterContextValue } from '../../context'
import { NOTIFICATIONS_CENTER_ACTIONS } from '../actions'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../../Agent/constants'

export const useNotificationServiceCall = (actionsCall = () => {}) => {
  const [notificationCenterState, dispatch] = useNotificationCenterContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [notificationCenterState, request]
}

export const useUploadBannerImage = () => useNotificationServiceCall(NOTIFICATIONS_CENTER_ACTIONS.uploadBannerImage)

export const useGetImageUploadUrl = (getFileData, fileUploadPath = PATH_FOR_AGENT_FILE_UPLOAD) => {
  const [{ uploadFileData }, uploadFileReq] = useUploadBannerImage()
  const [{ UPLOAD_FILE_LOADER }] = useLoaderContextValue()
  const [{ uploadFileStatus }, dispatchError] = useErrorContextValue()
  const that = useRef({
    type: '',
    id: ''
  })

  const customRequest = useCallback(({ file }, type, id) => {
    const formData = new FormData()
    const extFileName = file.name.split('.')[0].trim()
    const fileName = `${extFileName}-${Date.parse(new Date())}`
    formData.append('file', file)
    formData.append('path', `${fileUploadPath}/${fileName}`)
    formData.append('identifier', 'agent')
    that.current.type = type
    that.current.id = id
    uploadFileReq({ body: formData })
  }, [uploadFileReq, fileUploadPath])

  useEffect(() => {
    function resetErrorState (key) {
      dispatchError(resetError({
        [key]: undefined
      }))
    }
    if (uploadFileStatus === 'success' && that.current.type) {
      getFileData(uploadFileData.url, { ...that.current })
      resetErrorState('uploadFileStatus')
      that.current.type = ''
    } else if (uploadFileStatus && that.current.type) {
      showNotification('error', uploadFileStatus)
      resetErrorState('uploadFileStatus')
    }
  }, [getFileData, uploadFileData, uploadFileStatus, dispatchError])

  return {
    customRequest,
    UPLOAD_FILE_LOADER
  }
}

export const useGetNotificationCenterList = () => useNotificationServiceCall(NOTIFICATIONS_CENTER_ACTIONS.getNotificationCenterList)
export const useAddNotification = () => useNotificationServiceCall(NOTIFICATIONS_CENTER_ACTIONS.addNotification)
export const useEditNotification = () => useNotificationServiceCall(NOTIFICATIONS_CENTER_ACTIONS.editNotification)
