import { Row, Col, Button, Modal, Tag } from 'antd'
import LayoutContentStyle from '../../../../components/utility/layoutContent.style'
import { NotificationCenterStyle } from './index.style'
import { useState, useCallback, useRef, useEffect } from 'react'
import AddNotificationForm from '../components/AddNotificationForm'
import TableWrapper from '../../../containers/Notifications/pagination.style'
import { notificationStatus, NotificationTable, recipients, renderBroadCastStatus } from '../constant'
import NotificationFilter from '../components/NotificationFilter'
import { useGetNotificationCenterList } from '../state/hooks/useNotificationCenter'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { get } from 'lodash'

function NotificationCenter () {
  const [{ getNotificationsListData }, getNotificationsListRequest] = useGetNotificationCenterList()
  const [{ GET_NOTIFICATIONS_LIST_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    getNotificationsListRequest()
  }, [getNotificationsListRequest])

  const getNotificationTableData = useCallback(() => {
    if (getNotificationsListData?.data) {
      const updatedNotificationList = JSON.parse(JSON.stringify(getNotificationsListData?.data))
      return updatedNotificationList?.map((item, index) => {
        item.number = index + 1
        item.notification_status = renderBroadCastStatus(item.notification_status)
        return item
      })
    }
  }, [getNotificationsListData])

  const that = useRef({
    recipients: recipients(),
    notificationStatus: notificationStatus(),
    notificationData: {}
  })
  const childRef = useRef()
  const [page, setPage] = useState(1)
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [isFilterVisible, setIsFilterVisible] = useState('')
  const [notificationColumns, setNotificationColumns] = useState([])
  const [isChange, setIsChange] = useState(false)
  const [showNewForm, setShowNewForm] = useState(false)

  const closeNewForm = useCallback(() => {
    setShowNewForm(false)
    that.current.notificationData = {}
  }, [])

  const notificationListHandler = useCallback((payload = {}) => {
    getNotificationsListRequest(payload)
  }, [getNotificationsListRequest])

  const handleTableChange = useCallback((pagination) => {
    const { pageSize, current } = pagination
    const finalFilter = {
      page: current,
      limit: pageSize
    }
    setPage(current)
    notificationListHandler(finalFilter)
  }, [
    notificationListHandler
  ])

  const handleInputChange = useCallback((event, identifier) => {
    setSearchTextQuery({
      ...searchTextQuery,
      [identifier]: event.target.value
    })
    setIsChange(true)
  }, [searchTextQuery])

  const onSearchDate = useCallback((e, identifier) => {
    const { startDate, endDate } = e
    const startDateStr = `${startDate} 00:00:00`
    const endDateStr = `${endDate} 23:59:59`
    const dateKeyDict = {
      createdAt: 'createdAt'
    }
    const dateKey = dateKeyDict[identifier] || identifier
    const date = {}
    if (startDate) {
      date[`${dateKey}_start`] = startDateStr
    }
    if (endDate) {
      date[`${dateKey}_end`] = endDateStr
    }
    const finalFilter = {
      ...searchTextQuery,
      ...date
    }
    setSearchTextQuery({
      ...searchTextQuery,
      ...date
    })
    setIsFilterVisible('')
    notificationListHandler(finalFilter)
    setIsChange(true)
  }, [
    searchTextQuery, notificationListHandler
  ])

  const handleSearch = useCallback((e) => {
    e.preventDefault()
    setIsFilterVisible('')
    notificationListHandler(searchTextQuery)
  }, [searchTextQuery, notificationListHandler])

  const handleDetailPage = useCallback((data) => {
    that.current.notificationData = data
    setShowNewForm(true)
  }, [])

  const getListTable = useCallback(() => {
    return NotificationTable({
      handleDetailPage,
      searchTextQuery,
      isFilterVisible,
      handleInputChange,
      handleSearch,
      setIsFilterVisible,
      isChange,
      onSearchDate,
      ...that.current
    })
  }, [
    isFilterVisible, isChange, searchTextQuery, handleInputChange,
    handleSearch, onSearchDate, handleDetailPage
  ])

  useEffect(() => {
    setNotificationColumns(getListTable())
  }, [isFilterVisible, searchTextQuery, getListTable])

  const handleClear = () => {
    notificationListHandler()
    childRef.current.handleResetField()
    setSearchTextQuery({})
  }

  const removeFilter = (filterName) => {
    const updatedSearchQuery = { ...searchTextQuery }
    delete updatedSearchQuery[filterName]
    setSearchTextQuery(updatedSearchQuery)
    notificationListHandler(updatedSearchQuery)
  }

  const handlePushNotificationSuccess = () => {
    getNotificationsListRequest()
    setShowNewForm(false)
    that.current.notificationData = {}
  }

  return (
    <NotificationCenterStyle>
      <LayoutContentStyle>
        {
          showNewForm &&
            <Modal
              style={{ top: '5%' }}
              footer={null}
              visible={showNewForm}
              onCancel={closeNewForm}
            >
              <AddNotificationForm defaultValue={that.current.notificationData} onSuccessfullAddition={handlePushNotificationSuccess} />
            </Modal>
        }
        <Row type='flex' justify='space-between'>
          <Col>
            <h3><b>Notification Center</b></h3>
          </Col>
          <Col>
            <Button
              className='mb-10 mr-30'
              type='primary'
              htmlType='button'
              onClick={() => { setShowNewForm(true) }}
            >
              Add New Post
            </Button>
            <Button
              className='mb-10'
              type='danger'
              htmlType='button'
              onClick={handleClear}
            >
              Clear Filter
            </Button>
          </Col>
        </Row>
        <Row>
          <Col>
            <h4><b>Filter</b></h4>
          </Col>
        </Row>
        <br />

        <NotificationFilter ref={childRef} notificationListHandler={notificationListHandler} />

        {
          Object.keys(searchTextQuery).map(key => (
            <Tag
              className='search-tag'
              key={searchTextQuery[key]}
              color='purple'
              closable='closable'
              onClose={() => removeFilter(key)}
            >
              {searchTextQuery[key]}
            </Tag>
          ))
        }

        <div className='mt-10'>
          <TableWrapper
            columns={notificationColumns}
            bordered
            rowKey={record => record.number}
            dataSource={getNotificationTableData() || []}
            pagination={{
              pageSize: 20,
              total: get(getNotificationsListData?.meta_data, 'total_records', ''),
              current: page
            }}
            loading={GET_NOTIFICATIONS_LIST_LOADER}
            onChange={handleTableChange}
          />
        </div>
      </LayoutContentStyle>
    </NotificationCenterStyle>
  )
}

export default NotificationCenter
