import { FormStyle } from './index.style'
import { Form, Select, Button, Row, Modal } from 'antd'
import renderFormItemsUtil from '../../../../../helpers/renderFormItems'
import { useState, useCallback, useRef, useEffect } from 'react'
import get from 'lodash/get'
import { renderPushNotificationRequestType } from '../../constant'
import ScheduleNotification from '../ScheduleNotification'
import moment from 'moment-timezone'
import { useAddNotification } from '../../state/hooks/useNotificationCenter'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import CircularLoader from '../../../../../components/CircularLoader'
import UploadBannerImage from '../UploadBannerImage'
import { showNotification } from '../../../../../components/ShowNotification'

function AddNotificationForm (props) {
  const parentRef = useRef()
  const { form, defaultValue, onSuccessfullAddition } = props
  const [Img, setImg] = useState(get(defaultValue?.extra_data, 'image', ''))
  const [isImageUploading, setImageUploadingStatus] = useState(false)
  const [recipients, setSelectedRecipientType] = useState(get(defaultValue, 'recipients', 'ALL'))
  const [openSchedulePopUp, setSchedulePopUpStatus] = useState(false)
  const isFieldDisabled = get(defaultValue, 'notification_status', '') === 'Published'

  const [, addNotificationRequest] = useAddNotification()
  const [{ ADD_NOTIFICATION_LOADER }] = useLoaderContextValue()
  const [{ addNotificationStatus, addNotificationErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()

  useEffect(() => {
    if (addNotificationStatus === 'success') {
      onSuccessfullAddition()
      setSchedulePopUpStatus(false)
      resetError(['addNotificationStatus'])
    } else if (addNotificationStatus) {
      const message = addNotificationErrorData?.message
      if (addNotificationErrorData?.error_code === 'PP-PUSH-NOTIF-DATA-NOT-UNIQUE') {
        showNotification('error', message)
      }
      resetError(['addNotificationStatus', 'addNotificationErrorData'])
    }
  }, [
    addNotificationStatus, resetError, addNotificationErrorData?.message,
    onSuccessfullAddition, addNotificationErrorData?.error_code
  ])

  const handleTypeSelection = useCallback((value) => {
    setSelectedRecipientType(value)
  }, [])

  const renderFormItems = useCallback((item) => {
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: form.getFieldDecorator,
      getFieldValue: form.getFieldValue
    })
  }, [form])

  const renderForm = useCallback((formData) => {
    return (
      formData.map((item, index) => (
        renderFormItems(item)
      ))
    )
  }, [renderFormItems])

  const handleValidation = (docType, extraData = {}) => {
    setSchedulePopUpStatus(false)
    form.validateFields((err, values) => {
      if (!err) {
        const finalData = {
          ...values,
          recipients,
          image: Img,
          request_type: docType,
          ...extraData
        }

        if (defaultValue.id) {
          finalData.id = defaultValue.id
        }
        addNotificationRequest(finalData)
      }
    })
  }

  const handleAddNewNotification = (docType) => {
    if (docType === 'PUSH-NOTIF-SCHEDULED') {
      form.validateFields((err) => {
        if (!err) {
          setSchedulePopUpStatus(true)
        }
      })
    } else {
      handleValidation(docType)
    }
  }

  const handleScheduleNotificationPopUp = () => {
    if (parentRef.current.getFieldValue('scheduled-at')) {
      handleValidation('PUSH-NOTIF-SCHEDULED', {
        scheduled_at: moment.utc(parentRef.current.getFieldValue('scheduled-at')).format('YYYY-MM-DD HH:mm:ss')
      })
    }
  }

  return (
    <FormStyle>
      <CircularLoader isSpining={ADD_NOTIFICATION_LOADER}>
        <Form>
          {
            renderForm([
              {
                name: 'title',
                title: 'Title',
                subTitle: 'title',
                type: 'textarea',
                placeholder: 'Enter the Title',
                max: 100,
                min: 1,
                defaultValue: get(defaultValue, 'title', ''),
                disabled: isFieldDisabled,
                extra: '* max 100 characters are allowed'
              },
              {
                name: 'description',
                title: 'Content',
                placeholder: 'Enter the Content',
                type: 'textarea',
                max: 800,
                defaultValue: get(defaultValue, 'description', ''),
                disabled: isFieldDisabled,
                extra: '* max 800 characters are allowed'
              }
            ])
          }
          <p>
            Upload Image
          </p>
          <UploadBannerImage
            onSave={(file) => setImg(file)}
            name='notification_image'
            img={Img}
            isNew={!Img}
            fileType='.png,.jpg,.jpeg'
            onRemove={() => setImg('')}
            disabled={isFieldDisabled}
            isFileUploading={status => setImageUploadingStatus(status)}
          />
          <p>
            Recipients
          </p>
          <Select
            placeholder='Pilih ...'
            value={recipients}
            className='mb-16'
            onChange={handleTypeSelection}
            disabled={isFieldDisabled}
          >
            <Select.Option value='ALL'>All</Select.Option>
            <Select.Option value='aggregator' disabled>Aggregator</Select.Option>
            <Select.Option value='marketing' disabled>Marketing Team</Select.Option>
          </Select>
          <br />
          {
            get(defaultValue, 'notification_status', '') !== 'Published' && (
              <Row type='flex' justify='space-around' className='mt-20'>
                {
                  renderPushNotificationRequestType.map((item, index) => (
                    <Button
                      key={index}
                      className='mb-10'
                      type='primary'
                      htmlType='button'
                      onClick={() => handleAddNewNotification(item.type)}
                      disabled={isImageUploading}
                    >
                      {item.title}
                    </Button>
                  ))
                }
              </Row>
            )
          }
          {openSchedulePopUp && (
            <Modal
              visible={openSchedulePopUp}
              onCancel={() => setSchedulePopUpStatus(false)}
              onOk={handleScheduleNotificationPopUp}
            >
              <ScheduleNotification ref={parentRef} defaultValue={get(defaultValue, 'published_at', '')} />
            </Modal>
          )}
        </Form>
      </CircularLoader>
    </FormStyle>
  )
}

const wrapperNewForm = Form.create()(AddNotificationForm)

export default wrapperNewForm
