import urls from '../../../../config/urls'
import { getHeaderUploadFile } from '../../../../helpers/utility'
import { uploadPolicyFileApi } from '../../Agent/config/urls'

const configUrl = urls.url

export const NOTIFICATIONS_CENTER_ACTIONS = {
  GET_NOTIFICATIONS_LIST_REQUEST: 'GET_NOTIFICATIONS_LIST_REQUEST',
  GET_NOTIFICATIONS_LIST: 'GET_NOTIFICATIONS_LIST',

  ADD_NOTIFICATION_REQUEST: 'ADD_NOTIFICATION_REQUEST',
  ADD_NOTIFICATION: 'ADD_NOTIFICATION',

  EDIT_NOTIFICATION_REQUEST: 'EDIT_NOTIFICATION_REQUEST',
  EDIT_NOTIFICATION: 'EDIT_NOTIFICATION',

  UPLOAD_FILE_REQUEST: 'UPLOAD_FILE_REQUEST',
  UPLOAD_FILE: 'UPLOAD_FILE',

  getNotificationCenterList: (payload = {}) => ({
    type: NOTIFICATIONS_CENTER_ACTIONS.GET_NOTIFICATIONS_LIST_REQUEST,
    payload: {
      query: payload,
      method: 'GET',
      url: configUrl.getNotificationCenterListApi
    }
  }),

  addNotification: (payload = {}) => ({
    type: NOTIFICATIONS_CENTER_ACTIONS.ADD_NOTIFICATION_REQUEST,
    payload: {
      body: payload,
      method: 'POST',
      url: configUrl.pushNotificationsApi
    }
  }),

  editNotification: (payload = {}) => ({
    type: NOTIFICATIONS_CENTER_ACTIONS.EDIT_NOTIFICATION_REQUEST,
    payload: {
      ...payload,
      method: 'PUT',
      url: configUrl.editNotificationApi(payload.id)
    }
  }),

  uploadBannerImage: (payload) => ({
    type: NOTIFICATIONS_CENTER_ACTIONS.UPLOAD_FILE_REQUEST,
    payload: {
      ...payload,
      headers: getHeaderUploadFile(),
      url: uploadPolicyFileApi,
      method: 'POST'
    }
  })
}
