import { NOTIFICATIONS_CENTER_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case NOTIFICATIONS_CENTER_ACTIONS.ADD_NOTIFICATION:
    case NOTIFICATIONS_CENTER_ACTIONS.GET_NOTIFICATIONS_LIST:
    case NOTIFICATIONS_CENTER_ACTIONS.UPLOAD_FILE:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
