import { Button, Col, DatePicker, Form, Input, Row, Select } from 'antd'
import moment from 'moment-timezone'
import React, { useCallback, useImperativeHandle, useRef } from 'react'

const NotificationFilter = (props) => {
  const { form, notificationListHandler, parentRef } = props
  const that = useRef({})

  useImperativeHandle(parentRef, () => ({
    handleResetField: () => {
      form.resetFields()
      that.current = {}
    }
  }))

  const handleApplyFilter = () => {
    form.validateFields((err, value) => {
      if (!err) {
        const {
          title, recipients, notification_status: notificationStatus,
          creator
        } = value
        notificationListHandler({
          title,
          recipients,
          notification_status: notificationStatus,
          creator,
          ...(that.current)
        })
      }
    })
  }

  const handleDatePickerChange = (key, value) => {
    if (['created_at_start', 'created_at_end'].includes(key)) {
      value = key === 'created_at_start' ? `${value} 00:00:00` : `${value} 23:59:59`
      that.current[key] = value
    }

    if (key === 'published_at') {
      const date = {}
      date[`${key}_start`] = `${value} 00:00:00`
      date[`${key}_end`] = `${value} 23:59:59`

      form.setFieldsValue({
        notification_status: value ? 'PUSH-NOTIF-PUBLISHED' : 'PUSH-NOTIF-DRAFT'
      })

      that.current = {
        ...that.current,
        ...date
      }
    }
  }

  const handleDisabledDate = (current, maxDate, minDate, name) => {
    if (name === 'created_at_start' && maxDate) {
      return current > maxDate + (24 * 60 * 60 * 1000)
    } else if (name === 'created_at_end' && minDate) {
      return current < minDate
    }
  }

  const handleSelect = (val) => {
    if (
      ['PUSH-NOTIF-DRAFT', 'PUSH-NOTIF-SCHEDULED'].includes(val) &&
      form.getFieldValue('published_at')
    ) {
      form.setFieldsValue({
        published_at: ''
      })
      delete that.current.published_at_start
      delete that.current.published_at_end
    }
  }

  const getFieldElement = useCallback(({
    name, placeholder, type, data = [], dropdownKey = 'code', dropdownValue = 'name',
    className, min, max
  }) => {
    let fieldElement = ''
    switch (type) {
      case 'text':
      case 'email':
        fieldElement = <Input type={type} placeholder={placeholder} />
        break
      case 'datepicker':
        fieldElement = (
          <DatePicker
            placeholder={placeholder}
            onChange={(val) => handleDatePickerChange(name, val ? moment(val).format('YYYY-MM-DD') : '')}
            format='YYYY-MM-DD'
            disabledDate={(current) => handleDisabledDate(current, max, min, name)}
          />
        )
        break
      case 'select':
        fieldElement = (
          <Select
            className={className}
            placeholder={placeholder}
            onSelect={(val, { props }) => handleSelect(val, props.children)}
          >
            {
              data.map((value) => (
                <Select.Option
                  value={value[dropdownKey]}
                  key={value[dropdownKey]}
                  disabled={value.isDisabled}
                >
                  {value[dropdownValue]}
                </Select.Option>
              ))
            }
          </Select>
        )
        break
      default:
        return null
    }
    return fieldElement
  }, [])

  const renderChildren = useCallback((item, index) => {
    const { getFieldDecorator } = form
    return (
      <Col className='filter-column' key={index}>
        <Form.Item>
          {getFieldDecorator(item.name)(getFieldElement(item))}
        </Form.Item>
      </Col>
    )
  }, [form, getFieldElement])

  const renderFilterItems = useCallback((item, index) => {
    const { getFieldDecorator } = form
    const fieldElement = getFieldElement(item)
    return (
      <Row type='flex' align='top' key={index}>
        <Col span={13} className='filter-row-title'>
          <b>{item.title}</b>
        </Col>
        {
          item.children
            ? (
              <Row type='flex' justify='space-between' className='filter-row-item'>
                {item.children.map((item, index) => renderChildren(item, index))}
              </Row>
              )
            : (
              <Form.Item>
                {getFieldDecorator(item.name, {
                  initialValue: item.type === 'select' ? item.defaultValue : ''
                })(fieldElement)}
              </Form.Item>
              )
        }
      </Row>
    )
  }, [form, renderChildren, getFieldElement])

  const renderFilterColumns = useCallback((formData = []) => {
    return (
      <Col className='filter-column'>
        {
          formData.map((item, index) => (
            renderFilterItems(item, index)
          ))
        }
      </Col>
    )
  }, [renderFilterItems])
  return (
    <Form>
      <Row type='flex' justify='space-between'>
        {
          renderFilterColumns([
            {
              name: 'title',
              title: 'Title',
              placeholder: 'Enter Title',
              type: 'text',
              defaultValue: ''
            },
            {
              name: 'recipients',
              title: 'Recipients',
              placeholder: 'Enter Recipient',
              type: 'select',
              defaultValue: 'ALL',
              className: 'wdth-180',
              data: [
                {
                  code: 'ALL',
                  name: 'All',
                  isDisabled: false
                },
                {
                  code: 'aggregator',
                  name: 'Aggregator',
                  isDisabled: true
                },
                {
                  code: 'marketing',
                  name: 'Marketing Team',
                  isDisabled: true
                }
              ]
            },
            {
              name: 'creator',
              title: 'Creator',
              placeholder: 'Enter Email',
              type: 'email',
              defaultValue: ''
            }
          ])
        }
        {
          renderFilterColumns([
            {
              title: 'Notification State',
              name: 'notification_status',
              placeholder: 'Select',
              type: 'select',
              className: 'wdth-180',
              defaultValue: 'PUSH-NOTIF-DRAFT',
              data: [
                {
                  code: 'PUSH-NOTIF-DRAFT',
                  name: 'Draft'
                },
                {
                  code: 'PUSH-NOTIF-SCHEDULED',
                  name: 'Scheduled'
                },
                {
                  code: 'PUSH-NOTIF-PUBLISHED',
                  name: 'Published'
                }
              ]
            },
            {
              name: 'createdAt',
              title: 'Created At',
              children: [
                {
                  name: 'created_at_start',
                  placeholder: 'Start Date',
                  type: 'datepicker',
                  max: form.getFieldValue('created_at_end')
                },
                {
                  name: 'created_at_end',
                  placeholder: 'End Date',
                  type: 'datepicker',
                  min: form.getFieldValue('created_at_start')
                }
              ]
            },
            {
              name: 'published_at',
              title: 'Published At',
              placeholder: 'Select Date',
              type: 'datepicker'
            }
          ])
        }
        <Col>
          <Button
            className='mb-10'
            type='primary'
            htmlType='button'
            onClick={handleApplyFilter}
          >
            Apply Filter
          </Button>
        </Col>
      </Row>
    </Form>
  )
}
const WrappedNotificationFilter = Form.create()(NotificationFilter)
export default React.forwardRef((props, ref) => <WrappedNotificationFilter parentRef={ref} {...props} />)
