import { DatePicker, Form } from 'antd'
import moment from 'moment-timezone'
import { range } from 'lodash'
import Cookies from 'universal-cookie'
import { ScheduleNotificationWrapper } from './index.style'

const cookies = new Cookies()

function ScheduleNotification ({ form, defaultValue }) {
  const userTimeZone = cookies.get('userProfile').user_timezone
  moment.tz.setDefault(userTimeZone)

  const getDefaultTime = () => {
    if (moment().minute() >= 30) {
      return moment(`${(moment().hour() + 1) % 24}:00:00`, 'HH:mm:ss')
    } else {
      return moment(`${moment().hour()}:30:00`, 'HH:mm:ss')
    }
  }

  const { getFieldDecorator } = form

  return (
    <ScheduleNotificationWrapper>
      <Form>
        <Form.Item
          label='Schedule'
        >
          {
            getFieldDecorator('scheduled-at', {
              initialValue: (defaultValue) ? moment(defaultValue) : ''
            })(
              <DatePicker
                showTime={{
                  format: 'HH:mm',
                  minuteStep: 30,
                  defaultValue: getDefaultTime()
                }}
                format='YYYY-MM-DD HH:mm:ss'
                showToday={false}
                disabledDate={d => d.isBefore(moment(), 'day')}
                disabledTime={(d) => ({
                  disabledHours: () => moment().hour() > 0 && d.isSame(moment(), 'day') ? range(0, moment().hour()) : [],
                  disabledMinutes: () => d.isSame(moment(), 'hour') ? moment().minute() > 30 ? [0, 30] : [0] : []
                })}
              />
            )
          }
        </Form.Item>
      </Form>
      {userTimeZone && (
        <p className='timezone'>{`Note: Schedule Time is in ${userTimeZone} Timezone`}</p>
      )}
    </ScheduleNotificationWrapper>
  )
}

export default Form.create()(ScheduleNotification)
